    50|export function getWireInstructions(): WireInstructions | null {
    51|  const bankName = readTrimmed(process.env.IVX_WIRE_BANK_NAME);
    52|  const routingNumber = readTrimmed(process.env.IVX_WIRE_ROUTING_NUMBER);
    53|  const accountNumber = readTrimmed(process.env.IVX_WIRE_ACCOUNT_NUMBER);
    54|  const accountName = readTrimmed(process.env.IVX_WIRE_ACCOUNT_NAME);
    55|  const bankAddress = readTrimmed(process.env.IVX_WIRE_BANK_ADDRESS);
    56|  const beneficiaryAddress = readTrimmed(process.env.IVX_WIRE_BENEFICIARY_ADDRESS);
    57|  const swiftCode = readTrimmed(process.env.IVX_WIRE_SWIFT_CODE) || undefined;
    58|
    59|  if (!bankName || !routingNumber || !accountNumber || !accountName || !bankAddress || !beneficiaryAddress) {
    60|    return null;
    61|  }
    62|
    63|  return {
