    77|export function generateWireReferenceCode(userId: string): string {
    78|  const base = userId.replace(/[^a-zA-Z0-9]/g, '').slice(0, 8).toUpperCase() || 'IVX';
    79|  const random = Math.floor(1000 + Math.random() * 8999);
    80|  return `IVX-${base}-${random}`;
