    83|export async function recordWireSubmission(input: WireSubmissionInput): Promise<WireSubmissionResult> {
    84|  try {
    85|    const id = `wire_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    86|
    87|    // TODO: persist to Supabase/DB here once schema is created.
    88|    // For now, log a sanitized record and alert the owner via SMS.
    89|    console.log('[IVXWireTransfer] submission received', {
    90|      id,
    91|      email: input.email,
    92|      amount: input.amount,
    93|      currency: input.currency,
    94|      sentAt: input.sentAt,
    95|      referenceCode: input.referenceCode,
    96|    });
    97|
    98|    const ownerPhone = readTrimmed(process.env.IVX_OWNER_RECOVERY_PHONE);
    99|    if (ownerPhone) {
   100|      const message = [
   101|        'IVX WIRE ALERT:',
   102|        `${input.name || 'Investor'} ${input.email ? `(${input.email})` : ''}`,
   103|        `reported a $${input.amount} ${input.currency} wire`,
   104|        `sent ${input.sentAt}`,
   105|        `ref: ${input.referenceCode}`,
   106|      ].filter(Boolean).join(' ').slice(0, 320);
