    11|// ── Observability metrics (in-memory, per-instance) ──────────────────────────
    12|
    13|type MetricsBucket = {
    14|  totalRequests: number;
    15|  totalErrors: number;
    16|  totalLatencyMs: number;
    17|  minLatencyMs: number;
    18|  maxLatencyMs: number;
    19|  p50LatencyMs: number;
    20|  p95LatencyMs: number;
    21|  p99LatencyMs: number;
    22|  statusCodes: Record<number, number>;
    23|  lastResetAt: string;
    24|};
    25|
    26|const metrics: MetricsBucket = {
    27|  totalRequests: 0,
    28|  totalErrors: 0,
    29|  totalLatencyMs: 0,
    30|  minLatencyMs: Infinity,
    31|  maxLatencyMs: 0,
    32|  p50LatencyMs: 0,
    33|  p95LatencyMs: 0,
    34|  p99LatencyMs: 0,
    35|  statusCodes: {},
    36|  lastResetAt: new Date().toISOString(),
    37|};
    38|
    39|// Latency samples for percentile calculation (ring buffer, max 1000)
    40|const LATENCY_SAMPLES_MAX = 1000;
    41|const latencySamples: number[] = [];
    42|
    43|function recordLatency(ms: number): void {
    44|  metrics.totalRequests++;
    45|  metrics.totalLatencyMs += ms;
    46|  if (ms < metrics.minLatencyMs) metrics.minLatencyMs = ms;
    47|  if (ms > metrics.maxLatencyMs) metrics.maxLatencyMs = ms;
    48|
    49|  if (latencySamples.length < LATENCY_SAMPLES_MAX) {
    50|    latencySamples.push(ms);
    51|  } else {
    52|    latencySamples[Math.floor(Math.random() * LATENCY_SAMPLES_MAX)] = ms;
    53|  }
    54|
    55|  // Recalculate percentiles every 50 requests
    56|  if (metrics.totalRequests % 50 === 0 && latencySamples.length > 0) {
    57|    const sorted = [...latencySamples].sort((a, b) => a - b);
    58|    metrics.p50LatencyMs = sorted[Math.floor(sorted.length * 0.5)] ?? 0;
    59|    metrics.p95LatencyMs = sorted[Math.floor(sorted.length * 0.95)] ?? 0;
    60|    metrics.p99LatencyMs = sorted[Math.floor(sorted.length * 0.99)] ?? 0;
    61|  }
    62|}
    63|
    64|function recordStatusCode(status: number): void {
    65|  metrics.statusCodes[status] = (metrics.statusCodes[status] ?? 0) + 1;
