    78|    ...metrics,
    79|    rps: uptimeSeconds > 0 ? Math.round((metrics.totalRequests / uptimeSeconds) * 100) / 100 : 0,
    80|    uptimeSeconds,
    81|    avgLatencyMs: metrics.totalRequests > 0 ? Math.round(metrics.totalLatencyMs / metrics.totalRequests) : 0,
