    99|// ── Request timeout middleware ───────────────────────────────────────────────
   100|
   101|const DEFAULT_TIMEOUT_MS = 30_000;
   102|const AI_TIMEOUT_MS = 120_000;
   103|
   104|function isAIEndpoint(path: string): boolean {
   105|  return path.includes('/owner-ai') ||
   106|    path.includes('/multimodal') ||
