   111|
   112|/**
   113| * Request timeout middleware — aborts long-running requests.
   114| * AI endpoints get 120s, everything else gets 30s.
   115| */
   116|export async function requestTimeoutMiddleware(context: Context, next: Next): Promise<Response | void> {
   117|  const timeoutMs = isAIEndpoint(context.req.path) ? AI_TIMEOUT_MS : DEFAULT_TIMEOUT_MS;
   118|  const controller = new AbortController();
   119|  const timeout = setTimeout(() => controller.abort(), timeoutMs);
   120|
   121|  try {
   122|    await next();
   123|  } catch (err) {
   124|    if (controller.signal.aborted) {
   125|      console.error('[IVX Enterprise] Request timeout', {
   126|        path: context.req.path,
   127|        timeoutMs,
   128|      });
   129|      return new Response(
   130|        JSON.stringify({ ok: false, error: 'request_timeout', timeoutMs }),
   131|        { status: 504, headers: { 'Content-Type': 'application/json' } },
   132|      );
   133|    }
   134|    throw err;
   135|  } finally {
   136|    clearTimeout(timeout);
   137|  }
