   156|/**
   157| * Lightweight compression middleware — compresses JSON responses larger than 1KB
   158| * using gzip when the client supports it. Uses Node's built-in zlib.
   159| */
   160|export async function compressionMiddleware(context: Context, next: Next): Promise<void> {
   161|  await next();
   162|
   163|  const acceptEncoding = context.req.header('accept-encoding') ?? '';
   164|  if (!acceptEncoding.includes('gzip') || context.res.status === 204) return;
   165|
   166|  const contentType = context.res.headers.get('content-type') ?? '';
