   177|
   178|const MAX_BODY_BYTES = 2 * 1024 * 1024; // 2MB
   179|const MAX_AI_BODY_BYTES = 16 * 1024 * 1024; // 16MB for AI/upload endpoints
   180|
   181|/**
   182| * Body size limit middleware — rejects oversized request bodies.
   183| */
   184|export async function bodyLimitMiddleware(context: Context, next: Next): Promise<Response | void> {
   185|  if (context.req.method === 'GET' || context.req.method === 'HEAD' || context.req.method === 'OPTIONS') {
   186|    await next();
