   203|// ── AI endpoint rate limiting ────────────────────────────────────────────────
   204|
   205|type AIRateBucket = {
   206|  tokens: number;
   207|  lastRefillMs: number;
   208|};
   209|
   210|const AI_BUCKETS = new Map<string, AIRateBucket>();
   211|const AI_RATE_BURST = 10;
   212|const AI_RATE_REFILL_PER_SEC = 0.5; // 1 request per 2 seconds
   213|
   214|function getAIRateKey(context: Context): string {
   215|  const auth = context.req.header('authorization') ?? '';
   216|  const ip = context.req.header('cf-connecting-ip') ??
   217|    context.req.header('x-real-ip') ??
   218|    (context.req.header('x-forwarded-for') ?? '').split(',')[0].trim() ??
   219|    'unknown';
   220|  const keySuffix = auth.length > 8 ? auth.slice(-8) : ip;
