   223|
   224|/**
   225| * AI rate limiting middleware — protects expensive LLM endpoints.
   226| * Allows 10 burst requests, refills 1 token per 2 seconds.
   227| */
   228|export async function aiRateLimitMiddleware(context: Context, next: Next): Promise<Response | void> {
   229|  if (!isAIEndpoint(context.req.path) || context.req.method !== 'POST') {
   230|    await next();
   231|    return;
   232|  }
   233|
   234|  const key = getAIRateKey(context);
   235|  const now = Date.now();
   236|  const bucket = AI_BUCKETS.get(key) ?? { tokens: AI_RATE_BURST, lastRefillMs: now };
   237|
   238|  const elapsedSec = Math.max(0, (now - bucket.lastRefillMs) / 1000);
   239|  bucket.tokens = Math.min(AI_RATE_BURST, bucket.tokens + elapsedSec * AI_RATE_REFILL_PER_SEC);
   240|  bucket.lastRefillMs = now;
   241|
   242|  if (bucket.tokens < 1) {
   243|    const needed = 1 - bucket.tokens;
   244|    const retryAfterSec = Math.max(1, Math.ceil(needed / AI_RATE_REFILL_PER_SEC));
   245|    AI_BUCKETS.set(key, bucket);
